318		 *
319		 * @since 1.6.10
320		 *
321		 * @return bool
322		 */
323		public function display_wrong_api_key() {
324			static $display;
325	
326			if ( isset( $display ) ) {
327				return $display;
328			}
329	
330			$display = false;
331	
332			if ( ! $this->user_can( 'wrong-api-key' ) ) {
333				return $display;
334			}
335	
336			if ( ! imagify_is_screen( 'bulk' ) ) {
337				return $display;
