404		 * Tell if the 'grid-view' notice should be displayed.
405		 *
406		 * @since 1.6.10
407		 *
408		 * @return bool
409		 */
410		public function display_grid_view() {
411			global $wp_version;
412			static $display;
413	
414			if ( isset( $display ) ) {
415				return $display;
416			}
417	
418			$display = false;
419	
420			if ( ! $this->user_can( 'grid-view' ) ) {
421				return $display;
422			}
423	
424			if ( ! imagify_is_screen( 'library' ) ) {
425				return $display;
