762		/**
763		 * Renew a dismissed Imagify notice.
764		 *
765		 * @since 1.6.10
766		 *
767		 * @param string $notice  A notice ID.
768		 * @param int    $user_id A user ID.
769		 */
770		public static function renew_notice( $notice, $user_id = 0 ) {
771			$user_id = $user_id ? (int) $user_id : get_current_user_id();
772			$notices = get_user_meta( $user_id, self::DISMISS_META_NAME, true );
773			$notices = $notices && is_array( $notices ) ? array_flip( $notices ) : [];
774	
775			if ( ! isset( $notices[ $notice ] ) ) {
776				return;
777			}
778	
779			unset( $notices[ $notice ] );
780			$notices = array_flip( $notices );
781			$notices = array_filter( $notices );
782			$notices = array_values( $notices );
783	
784			update_user_meta( $user_id, self::DISMISS_META_NAME, $notices );
785		}
