792		 *
793		 * @param  string $notice  A notice ID.
794		 * @param  int    $user_id A user ID.
795		 */
796		public static function dismiss_notice( $notice, $user_id = 0 ) {
797			$user_id = $user_id ? (int) $user_id : get_current_user_id();
798			$notices = get_user_meta( $user_id, self::DISMISS_META_NAME, true );
799			$notices = $notices && is_array( $notices ) ? array_flip( $notices ) : [];
800	
801			if ( isset( $notices[ $notice ] ) ) {
802				return;
803			}
804	
805			$notices   = array_flip( $notices );
806			$notices[] = $notice;
807			$notices   = array_filter( $notices );
808			$notices   = array_values( $notices );
809	
810			update_user_meta( $user_id, self::DISMISS_META_NAME, $notices );
811		}
