26			$doc = $this->get_file_contents();
27	
28			if ( is_wp_error( $doc ) ) {
29				return $doc;
30			}
31	
32			$marker = static::TAG_NAME;
33			$xpath  = new \DOMXPath( $doc );
34	
35			// Remove previous rules.
36			$old_nodes = $xpath->query( ".//*[starts-with(@name,'$marker')]" );
37	
38			if ( $old_nodes->length > 0 ) {
39				foreach ( $old_nodes as $old_node ) {
40					$old_node->parentNode->removeChild( $old_node );
41				}
42			}
43	
44			// No new contents? Stop here.
45			if ( ! $new_contents ) {
46				return $this->put_file_contents( $doc );
47			}
48	
49			$new_contents = preg_split( '/<!--\s+@parent\s+(.+?)\s+-->/', $new_contents, -1, PREG_SPLIT_DELIM_CAPTURE );
50			unset( $new_contents[0] );
51			$new_contents = array_chunk( $new_contents, 2 );
52	
53			foreach ( $new_contents as $i => $new_content ) {
54				$path        = rtrim( $new_content[0], '/' );
