235		 * @param  \DOMNode     $child A \DOMNode to be prepended.
236		 * @return \DOMNode            The \DOMNode node.
237		 */
238		protected function get_node( $doc, $xpath, $path, $child ) {
239			$nodelist = $xpath->query( $path );
240	
241			if ( $nodelist->length > 0 ) {
242				return $this->prepend_node( $nodelist->item( 0 ), $child );
243			}
244	
245			$path = explode( '/', $path );
246			$node = array_pop( $path );
247			$path = implode( '/', $path );
248	
249			$final_node = $doc->createElement( $node );
250	
251			if ( $child ) {
252				$final_node->appendChild( $child );
253			}
254	
255			return $this->get_node( $doc, $xpath, $path, $final_node );
