267		 * @param  \DOMNode $new_node       The \DOMNode to be prepended.
268		 * @return \DOMNode                 The \DOMNode containing the new node.
269		 */
270		protected function prepend_node( $container_node, $new_node ) {
271			if ( ! $new_node ) {
272				return $container_node;
273			}
274	
275			if ( $container_node->hasChildNodes() ) {
276				$container_node->insertBefore( $new_node, $container_node->firstChild );
277			} else {
278				$container_node->appendChild( $new_node );
279			}
280	
281			return $container_node;
